{"point":{"id":"analysis","title":"Static Architecture Analysis","rationale":"A separate TypeScript analysis pipeline extracts containment, lexical references, calls, ownership, and dependencies with explicit evidence provenance. It supports incremental reuse, partition metrics, deterministic artifacts, and joins from pinned diagram leaf ranges to source entities. The inspected CLI invokes it independently of the interactive backend.","sourcePaths":["application/core/static-analysis/ports.ts","infrastructure/core/static-analysis/analyzer.ts","infrastructure/core/static-analysis/context.ts","infrastructure/core/static-analysis/declarations.ts","infrastructure/core/static-analysis/incremental.ts","domain/core/static-analysis/schema.ts","domain/core/static-analysis/derive.ts","domain/core/static-analysis/sourceJoins.ts","scripts/analysis/analyze.ts"],"relationships":[{"pointId":"diagrams","label":"Defines joins from pinned diagram leaves to source entities","kind":"related"}]},"sources":[{"path":"application/core/static-analysis/ports.ts","text":"import type { AnalysisArtifact, AnalysisView } from '../../../domain/core/static-analysis/schema';

/** A selection limits fact emission; imports may still be read for symbol resolution. */
export interface StaticAnalysisRequest {
  repositoryRoot: string;
  repositoryId: string;
  tsconfigPath: string;
  includePaths: readonly string[];
  views: readonly AnalysisView[];
  frameworks: readonly ('react' | 'zustand' | 'tldraw' | 'controller')[];
  metrics: { partitions: readonly ('directory' | 'layer' | 'single-group')[]; shuffleSeed: number; shuffleSamples: number };
}

/** Wall time, RSS and timestamps are deliberately outside deterministic persisted facts. */
export interface StaticAnalysisResult {
  artifact: AnalysisArtifact;
  measurements: { elapsedMs: number; peakRssBytes: number; phasesMs?: Record<string, number> };
  /** Compiler mode used to reconstruct an identical snapshot during incremental assembly. */
  execution?: { semanticResolution: boolean };
}
export interface StaticAnalyzer {
  analyze(request: StaticAnalysisRequest): Promise<StaticAnalysisResult>;
}
"},{"path":"infrastructure/core/static-analysis/analyzer.ts","text":"import type { StaticAnalyzer } from '../../../application/core/static-analysis/ports';
import { AnalysisContext, sha } from './context';
import { Declarations } from './declarations';
import { deriveAnalysis } from '../../../domain/core/static-analysis/derive';
import { extractLexical } from './lexical';
import { Resources } from './resources';
import { extractCalls } from './calls';
import { extractFrameworks } from './frameworks';
import { extractDataflow } from './dataflow';
import { connectCallbackCandidates } from './callbacks';

export const staticAnalyzer: StaticAnalyzer = {
  async analyze(request) {
    const started = performance.now();
    const phasesMs: Record<string, number> = {}; let previous = started;
    const phase = (name: string) => { const now = performance.now(); phasesMs[name] = now - previous; previous = now; if (process.env.STATIC_ANALYSIS_PROFILE) console.error(JSON.stringify({ phase: name, elapsedMs: phasesMs[name], rss: process.memoryUsage().rss, heap: process.memoryUsage().heapUsed })); };
    const context = new AnalysisContext(request), declarations = new Declarations(context);
    phase('parse');
    declarations.index(); declarations.imports(); declarations.composition();
    phase('containment');
    const references = request.views.some(view => view !== 'containment') ? extractLexical(context, declarations) : [];
    phase('lexical');
    if (request.views.some(view => ['calls', 'ownership', 'dependencies'].includes(view))) {
      const resources = new Resources(context, declarations); resources.initialize();
      phase('resources');
      const sites = extractCalls(context, declarations); phase('calls');
      extractFrameworks(context, declarations, resources, sites); phase('frameworks');
      if (request.views.some(view => ['ownership', 'dependencies'].includes(view))) {
        declarations.prepareDataflow(); phase('flow-symbols');
        context.releaseCompiler();
        extractDataflow(context, declarations, resources, references, sites);
        connectCallbackCandidates(context, declarations, sites);
      }
      phase('dataflow');
    }
    const artifact = context.finish();
    phase('snapshot');
    context.release(); references.length = 0;
    declarations.declarationOwners.clear(); declarations.receivers.clear(); declarations.scopeBindings.clear();
    declarations.parameterFields.clear();
    deriveAnalysis(artifact, request.metrics, sha);
    phase('derive');
    return { artifact, execution: { semanticResolution: context.usedSemanticResolution }, measurements: { elapsedMs: performance.now() - started, peakRssBytes: process.resourceUsage().maxRSS * 1024, phasesMs } };
  },
};
"},{"path":"infrastructure/core/static-analysis/context.ts","text":"import { hash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import ts from 'typescript';
import { sourceClassification } from '../../../domain/core/static-analysis/classification';
import { sourceLineCount } from '../../../domain/core/static-analysis/sourceText';
import type { StaticAnalysisRequest } from '../../../application/core/static-analysis/ports';
import type { AnalysisArtifact, AnalysisEntity, AnalysisProvenance, AnalysisRange, AnalysisRelation, AnalysisView } from '../../../domain/core/static-analysis/schema';

export const sha = (value: string) => hash('sha256', value, 'hex');
export const ANALYZER_VERSION = '0.4.0';
export const compare = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;
export const callable = (node: ts.Node): node is ts.FunctionLikeDeclaration => ts.isFunctionDeclaration(node) || ts.isFunctionExpression(node)
  || ts.isArrowFunction(node) || ts.isMethodDeclaration(node) || ts.isConstructorDeclaration(node) || ts.isGetAccessorDeclaration(node) || ts.isSetAccessorDeclaration(node);
export const views: AnalysisView[] = ['containment', 'lexical', 'calls', 'ownership', 'dependencies'];
let previousProgram: ts.Program | undefined;

export function classify(relative: string): AnalysisEntity['metadata'] {
  const { runtime, owner, composition } = sourceClassification(relative);
  const layer = relative.includes('/__tests__/') || /\.(?:test|integration)\.tsx?$/.test(relative) ? 'test'
    : ({ src: 'ui', domain: 'domain', application: 'application', infrastructure: 'infrastructure', server: 'server', packages: 'package' } as const)[runtime as 'src'] ?? 'other';
  return { layer, feature: owner, compositionRoot: composition };
}

export class AnalysisContext {
  readonly root: string;
  private activeProgram?: ts.Program;
  get program(): ts.Program { if (!this.activeProgram) throw new Error('Analysis compiler context has been released'); return this.activeProgram; }
  private typeChecker?: ts.TypeChecker;
  private semanticReady = false;
  get usedSemanticResolution() { return this.semanticReady; }
  private compilerOptions!: ts.CompilerOptions;
  private compilerRoots!: string[];
  private compilerHost!: ts.CompilerHost;
  get checker() {
    if (!this.semanticReady) {
      const syntax = this.program, host = this.compilerHost;
      const semanticHost = { ...host, getSourceFile: (...args: Parameters<ts.CompilerHost['getSourceFile']>) => syntax.getSourceFile(args[0]) ?? host.getSourceFile(...args) };
